```{r featured-pubs}
library(tidyverse)
library(RefManageR)
library(htmltools)

# ── Helpers ────────────────────────────────────────────────
`%||%` <- function(a, b) if (is.null(a) || length(a) == 0) b else a

strip_braces <- function(x) {
  if (is.null(x) || length(x) == 0) return(NA_character_)
  gsub("[{}]", "", as.character(x), perl = TRUE)
}

normalize_link <- function(x) {
  y <- trimws(as.character(x))
  y[y == "" | tolower(y) == "na"] <- NA_character_
  bare_doi <- !is.na(y) & grepl("^10\\.", y)
  y[bare_doi] <- paste0("https://doi.org/", y[bare_doi])
  y
}

# ── Read bib, filter to featured = true ───────────────────
bib  <- ReadBib("publications/papers.bib", check = FALSE)
keys <- names(bib)

featured <- tibble(key = keys, entry = lapply(keys, function(k) bib[k])) |>
  filter(map_lgl(entry, ~ {
    val <- .x$featured %||% ""
    tolower(trimws(as.character(val))) == "true"
  })) |>
  mutate(
    title    = map_chr(entry, ~ strip_braces(.x$title %||% "")),
    year     = map_chr(entry, ~ {
      y <- .x$year %||% .x$date %||% ""
      if (is.list(y)) y$year %||% "" else as.character(y)
    }),
    journal  = map_chr(entry, ~ strip_braces(.x$journal %||% .x$booktitle %||% "")),
    doi_url  = map_chr(entry, ~ normalize_link(.x$doi %||% .x$url %||% NA_character_)),
    keywords = map(entry, ~ {
      kw <- .x$keywords %||% NA_character_
      if (is.na(kw) || length(kw) == 0) character(0)
      else strsplit(as.character(kw), ",\\s*")[[1]]
    })
  ) |>
  arrange(desc(year), title)

# ── Build individual card ──────────────────────────────────
build_featured_card <- function(title, year, journal, doi_url, keywords, ...) {
  title_node <- if (!is.na(doi_url) && nzchar(doi_url)) {
    tags$div(class = "featured-pub-title",
             tags$a(title, href = doi_url, target = "_blank", rel = "noopener"))
  } else {
    tags$div(class = "featured-pub-title", title)
  }

  kw_tags <- lapply(keywords, function(kw)
    tags$span(class = "pub-keyword-tag", kw))

  tags$div(
    class = "featured-pub",
    tags$div(class = "featured-pub-year", year),
    tags$div(
      title_node,
      tags$div(class = "featured-pub-journal", journal),
      tagList(kw_tags)
    )
  )
}

# ── Render section ─────────────────────────────────────────
# To feature a paper: add  featured = {true},  to its .bib entry.
if (nrow(featured) == 0) {
  tagList(tags$p(
    style = "color:var(--slate-light); font-style:italic; font-size:0.9rem;",
    HTML("Add <code>featured = {true},</code> to entries in papers.bib to display them here.")
  ))
} else {
  cards <- pmap(featured, build_featured_card)
  browsable(tags$div(
    class = "featured-pubs-section",
    tags$div(cards),
    tags$a(class = "view-all-link",
           href  = "publications.html",
           "View all publications →")
  ))
}
```

